10	
11	#include "ascir/Target/Asc/EmitAsc.h"
12	#include "ascir/Dialect/Asc/IR/Asc.h"
13	#include "ascir/Dialect/EmitAsc/IR/EmitAsc.h"
14	#include "mlir/IR/BuiltinAttributes.h"
15	
16	using namespace mlir;
17	using namespace mlir::emitasc;
18	
19	//===----------------------------------------------------------------------===//
20	// EmitAsc operations
21	//===----------------------------------------------------------------------===//
22	
23	LogicalResult mlir::emitasc::printOperation(CodeEmitter& emitter, emitasc::CallOpaqueOp op)
24	{
25	    auto& os = emitter.ostream();
26	
27	    FAIL_OR(emitter.emitAssignPrefix(*op.getOperation()));
28	    os << op.getCallee() << '(';
29	    llvm::interleaveComma(op.getOperands(), os, [&](Value operand) { os << emitter.getOrCreateName(operand); });
30	    os << ')';
31	
32	    return success();
33	}
34	
35	LogicalResult mlir::emitasc::printOperation(CodeEmitter& emitter, emitasc::CopyStructOp op)
36	{
37	    FAIL_OR(emitter.emitType(op.getLoc(), op.getType()));
38	    auto base = emitter.getOrCreateName(op.getBase());
39	    auto result = emitter.getOrCreateName(op.getResult());
40	    auto& os = emitter.ostream();
41	    os << ' ' << result << ";\n";
42	    os << "for (size_t i = 0; i < sizeof(" << result << "); i++) {\n";
43	    os.indent() << "auto byte = reinterpret_cast<";
44	    if (auto attr = dyn_cast_if_present<IntegerAttr>(op.getBase().getType().getMemorySpace())) {
45	        auto asInt = static_cast<uint8_t>(attr.getValue().getSExtValue());
46	        if (auto addrSpace = ascendc::symbolizeAddressSpace(asInt)) {
47	            emitter.emitAddressSpace(*addrSpace);
48	        }
49	    }
50	    os << "uint8_t*>(" << base << ")[i];\n";
51	    os << "reinterpret_cast<uint8_t*>(&" << result << ")[i] = byte;\n";
52	    os.unindent() << '}';
53	    return success();
54	}
55	
56	LogicalResult mlir::emitasc::printOperation(CodeEmitter& emitter, emitasc::DereferenceOp op)
57	{
58	    auto& os = emitter.ostream();
59	    FAIL_OR(emitter.emitType(op.getLoc(), op.getType()));
60	    os << "& " << emitter.getOrCreateName(op.getResult()) << " = *" << emitter.getOrCreateName(op.getBase());
61	    return success();
62	}
63	
64	LogicalResult mlir::emitasc::printOperation(CodeEmitter& emitter, emitasc::MemberOp op)
65	{
66	    auto& os = emitter.ostream();
67	    FAIL_OR(emitter.emitAssignPrefix(*op.getOperation()));
68	    os << emitter.getOrCreateName(op.getBase());
69	    if (isa<MemRefType>(op.getBase().getType()))
70	        os << "->";
71	    else
72	        os << '.';
73	    os << op.getField();
74	    return success();
75	}
76	
77	LogicalResult mlir::emitasc::printOperation(CodeEmitter& emitter, emitasc::MemberPtrOp op)
78	{
79	    auto& os = emitter.ostream();
80	
81	    FAIL_OR(emitter.emitAssignPrefix(*op.getOperation()));
82	    os << "reinterpret_cast<";
83	    FAIL_OR(emitter.emitType(op.getLoc(), op.getType()));
84	    os << ">(" << '&' << emitter.getOrCreateName(op.getBase()) << "->";
85	    if (auto attr = op.getFieldAttr()) {
86	        os << attr.str();
87	    } else {
88	        os << emitter.structFieldNamePrefix << op.getIndex();
89	    }
90	    os << ')';
91	
92	    return success();
93	}
94	
95	LogicalResult mlir::emitasc::printOperation(CodeEmitter& emitter, emitasc::DeclarePyStructOp op)
96	{
97	    auto& os = emitter.ostream();
98	    os << "#pragma pack(push, 8)\n";
99	    auto pType = dyn_cast<emitasc::PyStructType>(op.getPystruct());
100	    os << "struct " << pType.getNameAttr().getValue() << " {\n";
101	    os.indent();
102	    for (auto [typeAttr, nameAttr] : llvm::zip_equal(pType.getTypesAttr(), pType.getNamesAttr())) {
103	        FAIL_OR(emitter.emitType(op.getLoc(), cast<TypeAttr>(typeAttr).getValue()));
104	        os << " " << cast<StringAttr>(nameAttr).getValue() << ";\n";
105	    }
106	    os.unindent() << "};\n";
107	    os << "#pragma pack(pop)\n";
108	
109	    return success();
110	}
111	
112	LogicalResult mlir::emitasc::printOperation(CodeEmitter& emitter, emitasc::MemberRefOp op)
113	{
114	    auto& os = emitter.ostream();
115	
116	    FAIL_OR(emitter.emitType(op.getLoc(), op.getType()));
117	    os << "& " << emitter.getOrCreateName(op.getResult()) << " = reinterpret_cast<";
118	    FAIL_OR(emitter.emitType(op.getLoc(), op.getType()));
119	    os << "&>(" << emitter.getOrCreateName(op.getBase()) << "->";
120	    if (auto attr = op.getFieldAttr()) {
121	        os << attr.str();
122	    } else {
123	        os << emitter.structFieldNamePrefix << op.getIndex();
124	    }
125	    os << ')';
126	
127	    return success();
128	}
129	
130	LogicalResult mlir::emitasc::printOperation(CodeEmitter& emitter, emitasc::PtrOffsetOp op)
131	{
132	    FAIL_OR(emitter.emitAssignPrefix(*op.getOperation()));
133	    auto& os = emitter.ostream();
134	    os << emitter.getOrCreateName(op.getBase()) << " + ";
135	    if (auto offset = op.getDynamicOffset()) {
136	        os << emitter.getOrCreateName(offset);
137	    } else {
138	        FAIL_OR(emitter.emitAttribute(op.getLoc(), op.getStaticOffsetAttr()));
139	    }
140	    return success();
141	}
142	
143	LogicalResult mlir::emitasc::printOperation(CodeEmitter& emitter, emitasc::ReinterpretCastOp op)
144	{
145	    auto& os = emitter.ostream();
146	
147	    FAIL_OR(emitter.emitAssignPrefix(*op.getOperation()));
148	    os << "reinterpret_cast<";
149	    FAIL_OR(emitter.emitType(op.getLoc(), op.getType()));
150	    os << ">(" << emitter.getOrCreateName(op.getSource()) << ')';
151	
152	    return success();
153	}
154	
155	LogicalResult mlir::emitasc::printOperation(CodeEmitter& emitter, emitasc::SetMemberOp op)
156	{
157	    auto& os = emitter.ostream();
158	    os << emitter.getOrCreateName(op.getBase()) << "." << op.getField() << " = "
159	       << emitter.getOrCreateName(op.getValue());
160	
161	    return success();
162	}
163	
164	LogicalResult mlir::emitasc::printOperation(CodeEmitter& emitter, emitasc::VariableOp op)
165	{
166	    auto& os = emitter.ostream();
167	    auto loc = op.getLoc();
168	    auto res = op.getResult();
169	    auto resType = res.getType();
170	
171	    FAIL_OR(emitter.emitType(op.getLoc(), resType.getElementType()));
172	    os << ' ' << emitter.getOrCreateName(res);
173	
174	    for (auto size : resType.getShape()) {
175	        os << '[' << size << ']';
176	    }
177	
178	    os << '{';
179	    if (op.isStatic()) {
180	        FAIL_OR(emitter.emitAttribute(loc, op.getStaticInitAttr()));
181	    } else {
182	        os << emitter.getOrCreateName(op.getDynamicInit());
183	    }
184	    os << '}';
185	
186	    return success();
187	}
188	
189	LogicalResult mlir::emitasc::printOperation(CodeEmitter& emitter, emitasc::VerbatimOp op)
190	{
191	    auto& os = emitter.ostream();
192	    auto args = op.getArgs();
193	    auto code = op.getValue();
194	    if (args.empty()) {
195	        os << code;
196	        return success();
197	    }
198	    std::string result;
199	    result.reserve(2 * code.size()); // the factor of 2 is used to ensure sufficient space.
200	    size_t i = 1;
201	    size_t rem = 0;
202	    const char* data = code.data();
203	    while (i < code.size()) {
204	        if (code[i - 1] != '$') {
205	            i++;
206	            continue;
207	        }
208	        size_t j = i;
209	        while (j < code.size() && isdigit(code[j])) {
210	            j++;
211	        }
212	        if (j - i > 0) {
213	            size_t index = 0;
214	            auto fcResult = std::from_chars(data + i, data + j, index);
215	            if (!std::make_error_code(fcResult.ec) && index < args.size()) {
216	                std::copy(data + rem, data + i - 1, std::back_inserter(result));
217	                result += emitter.getOrCreateName(args[index]);
218	                rem = j;
219	                i = j;
220	                continue;
221	            }
222	        }
223	        i++;
224	    }
225	    std::copy(data + rem, data + code.size(), std::back_inserter(result));
226	    os << result;
227	    return success();
228	}
