LogicalResult printOperation(CodeEmitter& emitter, ModuleOp moduleOp)
{
    CodeEmitter::Scope scope(emitter);

    for (Operation& op : moduleOp) {
        if (failed(emitOperation(emitter, op, /*trailingSemicolon=*/false))) {
            return failure();
        }
    }
    return success();
}

