13	
14	#include "ascir/Dialect/Asc/IR/Asc.h"
15	#include "ascir/Target/Asc/EmitNameStack.h"
16	
17	#include "mlir/IR/BuiltinTypes.h"
18	#include "mlir/IR/Value.h"
19	#include "mlir/Support/IndentedOstream.h"
20	#include "llvm/ADT/ScopedHashTable.h"
21	
22	#include <functional>
23	#include <unordered_map>
24	namespace mlir {
25	
26	static constexpr const char* ascNamespace = "AscendC";
27	struct CodeEmitter {
28	    const std::string structFieldNamePrefix = "var";
29	
30	    static void emitCubeFormat(raw_ostream& os, ascendc::CubeFormat format);
31	
32	    static void emitTPosition(raw_ostream& os, ascendc::TPosition pos);
33	
34	    static void emitLayoutMode(raw_ostream& os, ascendc::LayoutMode layout);
35	
36	    explicit CodeEmitter(raw_ostream& os);
37	
38	    static void emitMatmulConfig(raw_ostream& os, ascendc::MatmulConfigAttr config);
39	
40	    LogicalResult emitAscMatmulSimplifiedTemplate(Location loc, Type type, bool emitAsUnsigned);
41	
42	    /// Emits attribute or returns failure.
43	    LogicalResult emitAttribute(Location loc, Attribute attr);
44	
45	    /// Emits type 'type' or returns failure.
46	    LogicalResult emitType(Location loc, Type type, bool emitAsUnsigned = false);
47	
48	    /// Emits array of types as a std::tuple of the emitted types.
49	    /// - emits void for an empty array;
50	    /// - emits the type of the only element for arrays of size one;
51	    /// - emits a std::tuple otherwise;
52	    LogicalResult emitTypes(Location loc, ArrayRef<Type> types);
53	
54	    /// Emits a variable declaration for a result of an operation.
55	    LogicalResult emitVariableDeclaration(OpResult opResult, bool trailingSemicolon);
56	
57	    /// Emits a label for the block.
58	    LogicalResult emitLabel(Block& block);
59	
60	    /// Emits the variable declaration and assignment prefix for 'op'.
61	    /// - emits separate variable followed by std::tie for multi-valued operation;
62	    /// - emits single type followed by variable for single result;
63	    /// - emits nothing if no value produced by op;
64	    /// Emits final '=' operator where a type is produced. Returns failure if
65	    /// any result type could not be converted.
66	    LogicalResult emitAssignPrefix(Operation& op);
67	
68	    /// Return the existing or a new label of a Block.
69	    StringRef getOrCreateName(Block& block);
70	
71	    /// Whether to map an mlir integer to a unsigned integer in C++.
72	    bool shouldMapToUnsigned(IntegerType::SignednessSemantics val);
73	
74	    /// Emits the operands of the operation. All operands are emitted in order.
75	    LogicalResult emitOperands(Operation& op);
76	
77	    /// Return the existing or a new name for a Value.
78	    StringRef getOrCreateName(Value val);
79	
80	    /// Emits an address space for MemRefType
81	    void emitAddressSpace(ascendc::AddressSpace addressSpace);
82	
83	    /// Emit MatmulType as template
84	    LogicalResult emitAscMatmulTypeTemplate(Location loc, Type type, bool emitAsUnsigned);
85	
86	    /// RAII helper function to manage entering/exiting C++ scopes.
87	    struct Scope {
88	        Scope(CodeEmitter& emitter)
89	            : valueMapperScope(emitter.valueMapper), blockMapperScope(emitter.blockMapper), emitter(emitter)
90	        {
91	            emitter.nameStack.pushScope();
92	        }
93	        ~Scope() { emitter.nameStack.popScope(); }
94	
95	    private:
96	        llvm::ScopedHashTableScope<Value, std::string> valueMapperScope;
97	        llvm::ScopedHashTableScope<Block*, std::string> blockMapperScope;
98	        CodeEmitter& emitter;
99	    };
100	
101	    /// Returns wether the Value is assigned to a C++ variable in the scope.
102	    bool hasValueInScope(Value val);
103	
104	    // Returns whether a label is assigned to the block.
105	    bool hasBlockLabel(Block& block);
106	
107	    /// Returns the output stream.
108	    raw_indented_ostream& ostream() { return os; };
109	
110	private:
111	    using ValueMapper = llvm::ScopedHashTable<Value, std::string>;
