28	{
29	    if (failed(emitter.emitAssignPrefix(*op))) {
30	        return failure();
31	    }
32	    auto& os = emitter.ostream();
33	    os << emitter.getOrCreateName(op.getMemref());
34	    for (Value index : op.getIndices()) {
35	        os << "[" << emitter.getOrCreateName(index) << "]";
36	    }
37	    return success();
38	}
